let selectedCreditCardId=null;
let selectedAccountId=null;
let creditStatementOffset=0;
let creditDetailTab='statement';
function pad2(n){return String(n).padStart(2,'0')}
function isoDate(d){return `${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())}`}
function cardStatementAnchor(card, base=new Date(), offset=0){
  const statement=Math.min(31,Math.max(1,Number(card.statement||15)));
  let y=base.getFullYear(), m=base.getMonth();
  const thisMonthDay=Math.min(statement,new Date(y,m+1,0).getDate());
  if(base.getDate()<=thisMonthDay){m-=1;}
  m+=offset;
  const end=new Date(y,m,Math.min(statement,new Date(y,m+1,0).getDate()));
  return end;
}
function cardPeriod(card, base=new Date(), offset=creditStatementOffset){
  const end=cardStatementAnchor(card,base,offset);
  const prevMonthLast=new Date(end.getFullYear(),end.getMonth(),0);
  const statement=Math.min(31,Math.max(1,Number(card.statement||15)));
  const startDay=Math.min(statement+1,prevMonthLast.getDate());
  const start=new Date(end.getFullYear(),end.getMonth()-1,startDay);
  return {start:isoDate(start),end:isoDate(end),offset};
}
function cardStatementDueDate(card, period){
  const dueDay=Math.min(31,Math.max(1,Number(card.due||5)));
  const end=new Date(period.end+'T00:00:00');
  const endDay=new Date(end.getFullYear(),end.getMonth()+1,0).getDate();
  const due=new Date(end.getFullYear(),end.getMonth(),Math.min(dueDay,endDay));
  if(due<=end) due.setMonth(due.getMonth()+1);
  return due;
}
function creditStatementKey(card, period){return `${card.id}|${period.start}|${period.end}`;}
function paymentBelongsToPeriod(payment, card, period){
  const key=creditStatementKey(card,period);
  if(payment.cardStatementKey) return payment.cardStatementKey===key;
  return payment.date>=period.start&&payment.date<=period.end;
}
function creditStatementPayments(card,period){
  return state.transactions.filter(t=>t.cardPayment&&String(t.toAccount)===String(card.id)&&paymentBelongsToPeriod(t,card,period)).sort((a,b)=>b.date.localeCompare(a.date));
}
function creditStatementStatus(card, period, paid, dueAmount){
  const dueDate=cardStatementDueDate(card,period), today=new Date(); today.setHours(0,0,0,0);
  if(dueAmount<=0) return {key:'paid',label:'已繳清',date:isoDate(dueDate)};
  if(paid>=dueAmount) return {key:'paid',label:'已繳清',date:isoDate(dueDate)};
  if(today>dueDate) return {key:'overdue',label:'已逾期',date:isoDate(dueDate)};
  if(paid>0) return {key:'partial',label:'部分繳款',date:isoDate(dueDate)};
  return {key:'unpaid',label:'待繳款',date:isoDate(dueDate)};
}
function accountHasTransactions(accountId){return state.transactions.some(t=>String(t.account)===String(accountId)||String(t.toAccount)===String(accountId))}
async function deleteAccount(accountId){
  const a=state.accounts.find(x=>String(x.id)===String(accountId)); if(!a)return;
  if(accountHasTransactions(accountId)){alert(`「${a.name}」仍有關聯交易，無法刪除。\n請先刪除或轉移與此帳戶相關的交易。`);return}
  if(Math.abs(Number(a.balance)||0)>0.000001){alert(`「${a.name}」目前餘額為 ${money(a.balance)}，請先將餘額歸零後再刪除。`);return}
  if(!confirm(`確定刪除帳戶「${a.name}」？`))return;
  state.accounts=state.accounts.filter(x=>String(x.id)!==String(accountId));
  if(String(selectedCreditCardId)===String(accountId))selectedCreditCardId=null;if(String(selectedAccountId)===String(accountId))selectedAccountId=null;
  await save();render();
}
function openAccountDetail(id){selectedAccountId=id;renderAccounts();setTimeout(()=>document.getElementById('accountDetail')?.scrollIntoView({behavior:'smooth',block:'start'}),30)}
function renderAccountDetail(){const el=document.getElementById('accountDetail'),a=acct(selectedAccountId);if(!el||!a||a.type==='card'){if(el)el.hidden=true;return}const ts=state.transactions.filter(t=>String(t.account)===String(a.id)||String(t.toAccount)===String(a.id)).sort((x,y)=>y.date.localeCompare(x.date));const income=ts.filter(t=>t.kind==='income'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const expense=ts.filter(t=>t.kind==='expense'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferIn=ts.filter(t=>t.kind==='transfer'&&String(t.toAccount)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferOut=ts.filter(t=>t.kind==='transfer'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);el.hidden=false;el.innerHTML=`<div class="account-detail-head"><div class="account-detail-title"><div class="account-detail-icon">${svgForAccount(a)}</div><div><h3>${a.name}</h3><div class="hint">${a.type==='cash'?'現金':'銀行'} · 帳戶明細</div></div></div><button type="button" class="secondary" data-close-account-detail>關閉</button></div><div class="account-detail-summary"><div class="account-summary-box"><span>目前餘額</span><b>${money(a.balance)}</b></div><div class="account-summary-box"><span>收入</span><b class="income-text">${money(income+transferIn)}</b></div><div class="account-summary-box"><span>支出</span><b class="expense-text">${money(expense+transferOut)}</b></div></div><div class="panel-head" style="margin:8px 0 10px"><h3 style="margin:0">相關交易</h3><span class="hint">${ts.length} 筆</span></div><div class="account-detail-list">${ts.length?ts.map(t=>{const c=cat(t.category);let sign=t.kind==='income'||(t.kind==='transfer'&&String(t.toAccount)===String(a.id))?'+':'−';let cls=sign==='+'?'income-text':'expense-text';return `<div class="account-detail-row"><span class="account-detail-date">${t.date}</span><div class="mini-icon">${c.icon}</div><div><b>${t.name}</b><div class="tx-meta">${t.merchant||t.note||'—'}${t.kind==='transfer'?' · 轉帳':''}</div></div><div class="amount ${cls}">${sign}${money(t.amount)}</div></div>`}).join(''):'<div class="empty">目前沒有相關交易</div>'}</div>`;el.querySelector('[data-close-account-detail]')?.addEventListener('click',()=>{selectedAccountId=null;el.hidden=true;renderAccounts()})}
function renderAccounts(){
  const cards=state.accounts.filter(a=>a.type==='card'), normal=state.accounts.filter(a=>a.type!=='card');
  const normalHtml=normal.map(a=>`<div class="account-tile" data-open-account="${a.id}" role="button" tabindex="0"><div class="account-tile-icon">${svgForAccount(a)}</div><div class="account-tile-main"><b>${a.name}</b><span>${a.type==='cash'?'現金':a.type==='bank'?'銀行':'帳戶'}</span></div><strong>${money(a.balance)}</strong><button type="button" class="account-delete-btn" data-delete-account="${a.id}" aria-label="刪除 ${a.name}">刪除</button></div>`).join('');
  const cardHtml=cards.map(a=>{let used=Math.max(0,Math.abs(a.balance)),limit=Math.max(0,a.limit||0),available=Math.max(0,limit-used),pct=limit?Math.min(100,used/limit*100):0;return `<div class="credit-card-row ${selectedCreditCardId===a.id?'active':''}" data-open-credit="${a.id}" role="button" tabindex="0"><div class="credit-card-row-main"><div class="cc-mini-icon">${svg('card')}</div><div><b>${a.name}</b><span>信用卡</span></div></div><div class="credit-card-row-amount"><small>已用 ${money(used)} / ${money(limit)}</small><strong>${money(available)}</strong><span>可用額度</span></div><button type="button" class="secondary cc-row-settings" data-open-card-settings="${a.id}">設定</button><button type="button" class="account-delete-btn" data-delete-account="${a.id}" aria-label="刪除 ${a.name}">刪除</button></div>`}).join('');
  accountGrid.innerHTML=`<div class="credit-list">${cards.length?cardHtml:'<div class="empty">尚無信用卡</div>'}</div><div class="normal-accounts">${normalHtml||'<div class="empty">尚無一般帳戶</div>'}</div>`;
  document.querySelectorAll('[data-open-credit]').forEach(b=>{b.onclick=(e)=>{if(e.target.closest('button'))return;openCreditAccount(b.dataset.openCredit)}});document.querySelectorAll('[data-open-account]').forEach(b=>{b.onclick=(e)=>{if(e.target.closest('button'))return;openAccountDetail(b.dataset.openAccount)}});document.querySelectorAll('[data-open-account]').forEach(b=>{b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();openAccountDetail(b.dataset.openAccount)}}});
  document.querySelectorAll('[data-open-card-settings]').forEach(b=>b.onclick=(e)=>{e.preventDefault();e.stopPropagation();nav('accounts');setTimeout(()=>document.getElementById('creditSettingsPanel')?.scrollIntoView({behavior:'smooth',block:'start'}),30)});
  document.querySelectorAll('[data-delete-account]').forEach(b=>b.onclick=async(e)=>{e.preventDefault();e.stopPropagation();await deleteAccount(b.dataset.deleteAccount)});
  if(selectedCreditCardId) renderCreditAccountDetail(); else if(creditAccountDetail) creditAccountDetail.hidden=true;
}
function openCreditAccount(id){selectedCreditCardId=id;creditStatementOffset=0;renderAccounts();setTimeout(()=>document.getElementById('creditAccountDetail')?.scrollIntoView({behavior:'smooth',block:'start'}),30)}
function renderCreditAccountDetail(){
  const el=document.getElementById('creditAccountDetail'), card=acct(selectedCreditCardId);
  if(!el||!card||card.type!=='card'){if(el)el.hidden=true;return}
  const period=cardPeriod(card,new Date(),creditStatementOffset);
  const today=isoDate(new Date());
  const statementTx=state.transactions.filter(t=>String(t.account)===String(card.id)&&t.kind==='expense'&&t.date>=period.start&&t.date<=period.end&&!t.cardPayment).sort((a,b)=>b.date.localeCompare(a.date));
  const unbilled=creditStatementOffset===0?state.transactions.filter(t=>String(t.account)===String(card.id)&&t.kind==='expense'&&t.date>period.end&&t.date<=today&&!t.cardPayment).sort((a,b)=>b.date.localeCompare(a.date)):[];
  const payments=creditStatementPayments(card,period);
  const current=statementTx.reduce((sum,t)=>sum+t.amount,0);
  const paid=payments.reduce((sum,t)=>sum+t.amount,0);
  const due=Math.max(0,current-paid);
  const outstanding=Math.max(0,Math.abs(card.balance));
  const limit=Math.max(0,card.limit||0),available=Math.max(0,limit-outstanding),pct=limit?Math.min(100,outstanding/limit*100):0;
  const sources=state.accounts.filter(a=>a.type!=='card'&&String(a.id)!==String(card.id));
  const status=creditStatementStatus(card,period,paid,current), nextDue=status.date;
  const unbilledTotal=unbilled.reduce((sum,t)=>sum+t.amount,0);
  const txList=(list,empty)=>list.length?list.map(t=>`<button type="button" class="credit-tx-row" data-credit-txid="${t.id}"><span class="credit-tx-main"><b>${t.name}</b><small>${t.date} · ${t.merchant||'—'}</small></span><span class="credit-tx-side"><b>${money(t.amount)}</b><small>${cat(t.category).name}</small></span></button>`).join(''):`<div class="credit-empty">${empty}</div>`;
  el.hidden=false;
  el.innerHTML=`
    <div class="credit-detail-head"><div><div class="eyebrow">信用帳戶</div><h3>${card.name}</h3><div class="hint">帳單週期 ${period.start} ～ ${period.end} · 繳款日 ${card.due||'—'} 日</div></div><div class="credit-period"><button type="button" data-credit-prev aria-label="上一期">‹</button><strong>${period.start} ～ ${period.end}</strong><button type="button" data-credit-next ${creditStatementOffset>=0?'disabled':''} aria-label="下一期">›</button></div></div>
    <div class="credit-cycle-status"><span class="credit-status credit-status-${status.key}">${status.label}</span><b>繳款截止 ${nextDue}</b></div>
    <div class="credit-summary"><div class="credit-summary-item"><span>本期帳單</span><b>${money(current)}</b></div><div class="credit-summary-item"><span>本期已繳</span><b class="green">${money(paid)}</b></div><div class="credit-summary-item"><span>本期未繳</span><b>${money(due)}</b></div><div class="credit-summary-item"><span>目前欠款</span><b>${money(outstanding)}</b></div></div>
    <div class="credit-bar-row"><span>可用額度 ${money(available)}</span><span>額度 ${money(limit)} · ${pct.toFixed(0)}%</span></div><div class="credit-bar"><i style="width:${pct}%"></i></div>
    <div class="credit-tabs" role="tablist" aria-label="信用卡交易狀態"><button type="button" class="credit-tab ${creditDetailTab==='statement'?'active':''}" data-credit-tab="statement">本期帳單 <b>${statementTx.length}</b></button><button type="button" class="credit-tab ${creditDetailTab==='unbilled'?'active':''}" data-credit-tab="unbilled">未出帳 <b>${unbilled.length}</b></button></div>
    ${creditDetailTab==='statement'?`<div class="credit-bill-summary"><div><span>本期應繳</span><b>${money(current)}</b></div><div><span>已繳</span><b class="green">${money(paid)}</b></div><div><span>尚欠</span><b>${money(due)}</b></div></div><div class="credit-section"><div class="credit-section-head"><h4>繳款記錄</h4><button class="ghost" data-inline-payment="${card.id}" ${sources.length&&due>0?'':'disabled'}>＋ 新增繳款</button></div><div id="creditPaymentForm" class="credit-payment-form" hidden></div>${payments.length?payments.map(p=>`<div class="payment-record"><div><b>${p.name}</b><div class="meta">${p.date} · ${acct(p.account).name}</div></div><div class="amount">${money(p.amount)}</div><span class="hint">已完成</span></div>`).join(''):'<div class="credit-empty">本期沒有繳款記錄</div>'}</div><div class="credit-section"><div class="credit-section-head"><h4>本期交易明細</h4><span class="hint">${statementTx.length} 筆 · ${money(current)}</span></div><div class="credit-tx-list">${txList(statementTx,'本期尚無交易')}</div></div>`:`<div class="credit-unbilled-card"><div><span>未出帳金額</span><b>${money(unbilledTotal)}</b></div><small>${unbilled.length} 筆 · ${creditStatementOffset===0?'結帳日後新增的消費':'上一期／歷史帳單不顯示未出帳'}</small></div><div class="credit-section"><div class="credit-section-head"><h4>未出帳交易</h4><span class="hint">${unbilled.length} 筆</span></div><div class="credit-tx-list">${txList(unbilled,'目前沒有未出帳交易')}</div></div>`}`;
  const payBtn=el.querySelector('[data-inline-payment]'); if(payBtn)payBtn.onclick=()=>showInlinePayment(card.id,period);
  el.querySelectorAll('[data-credit-tab]').forEach(b=>b.onclick=()=>{creditDetailTab=b.dataset.creditTab;renderCreditAccountDetail()});
  el.querySelectorAll('[data-credit-txid]').forEach(b=>b.onclick=()=>{const t=state.transactions.find(x=>String(x.id)===String(b.dataset.creditTxid));if(t)openTx('expense',t)});
  const prev=el.querySelector('[data-credit-prev]'); if(prev)prev.onclick=()=>{creditStatementOffset--;creditDetailTab='statement';renderCreditAccountDetail()};
  const next=el.querySelector('[data-credit-next]'); if(next)next.onclick=()=>{if(creditStatementOffset<0){creditStatementOffset++;creditDetailTab='statement';renderCreditAccountDetail()}};
}
function showInlinePayment(cardId,periodArg=null){
  const wrap=document.getElementById('creditPaymentForm'); if(!wrap)return;
  const card=acct(cardId), period=periodArg||cardPeriod(card,new Date(),creditStatementOffset), payments=creditStatementPayments(card,period);
  const statementTotal=state.transactions.filter(t=>String(t.account)===String(card.id)&&t.kind==='expense'&&t.date>=period.start&&t.date<=period.end&&!t.cardPayment).reduce((s,t)=>s+t.amount,0);
  const paid=payments.reduce((s,t)=>s+t.amount,0);
  const statementDue=Math.max(0,statementTotal-paid);
  const outstanding=Math.max(0,Math.abs(card.balance));
  const maxAmount=Math.min(statementDue,outstanding);
  const sources=state.accounts.filter(a=>a.type!=='card'&&String(a.id)!==String(cardId));
  wrap.hidden=false;
  if(!sources.length){wrap.innerHTML='<div class="credit-empty">沒有可用的扣款帳戶。</div>';return}
  if(maxAmount<=0){wrap.innerHTML='<div class="credit-empty">本期帳單已經繳清。</div>';return}
  wrap.innerHTML=`<div class="credit-payment-title"><b>繳交 ${period.start} ～ ${period.end} 帳單</b><span>本期尚欠 ${money(maxAmount)}</span></div><div class="credit-payment-grid"><label>繳款金額<input id="inlinePayAmount" type="number" min=1 max="${maxAmount}" value="${maxAmount}"></label><label>扣款帳戶<select id="inlinePaySource">${sources.map(a=>`<option value="${a.id}">${a.name}（${money(a.balance)}）</option>`).join('')}</select></label></div><div class="credit-payment-actions"><button type="button" class="secondary" id="inlinePayCancel">取消</button><button type="button" class="primary" id="inlinePayConfirm">確認繳款</button></div>`;
  wrap.querySelector('#inlinePayCancel').onclick=()=>{wrap.hidden=true};
  wrap.querySelector('#inlinePayConfirm').onclick=async()=>{
    const source=acct(wrap.querySelector('#inlinePaySource').value);
    const raw=Number(wrap.querySelector('#inlinePayAmount').value||0);
    const amount=Math.min(Math.max(0,raw),maxAmount);
    if(!amount)return alert('請輸入有效繳款金額');
    if(source.balance<amount&&!confirm(`「${source.name}」餘額不足 ${money(amount)}，仍要繼續？`))return;
    source.balance-=amount;
    card.balance+=amount;
    state.transactions.push({id:id(),date:isoDate(new Date()),name:`${card.name} 繳款`,amount,kind:'transfer',category:'',account:source.id,toAccount:card.id,note:'信用卡繳款',cardPayment:true,cardStatementKey:creditStatementKey(card,period)});
    await save();
    render();
    openCreditAccount(card.id);
  };
}

function expenseAmountForCategory(t,categoryId){if(t.kind!=='expense')return 0;if(Array.isArray(t.splits)&&t.splits.length)return t.splits.filter(s=>s.category===categoryId).reduce((a,s)=>a+s.amount,0);return t.category===categoryId?t.amount:0}
function renderBars(){let ts=monthTx().filter(t=>t.kind==='expense'),tot=ts.reduce((a,t)=>a+t.amount,0);categoryBars.innerHTML=state.categories.filter(c=>c.kind==='expense').map(c=>{let v=ts.reduce((a,t)=>a+expenseAmountForCategory(t,c.id),0);return `<div class="barline"><div class="barline-head"><span>${c.icon} ${c.name}</span><b>${money(v)}</b></div><div class="barline-track"><i style="width:${tot?v/tot*100:0}%"></i></div></div>`}).join('');assetBars.innerHTML=state.accounts.map(a=>`<div class="barline"><div class="barline-head"><span>${a.name}</span><b>${money(a.balance)}</b></div><div class="barline-track"><i style="width:${Math.max(4,Math.abs(a.balance)/Math.max(1,...state.accounts.map(x=>Math.abs(x.balance)))*100)}%"></i></div></div>`).join('');trendChart.innerHTML='<div class="empty">趨勢資料會隨交易自動更新</div>'}
function renderCardSettings(){let cards=state.accounts.filter(a=>a.type==='card');cardSettingsEl.innerHTML=cards.length?cards.map(a=>`<div class="cc-setting-card" data-card-setting="${a.id}"><div class="cc-setting-head"><div class="cc-mini-icon">▣</div><div><b>${a.name}</b><span>信用額度 ${money(a.limit||0)} · 結帳日 ${a.statement||15} 日 · 繳款日 ${a.due||5} 日</span></div></div><div class="cc-setting-fields"><label>信用額度<input data-field="limit" type="number" min="0" value="${a.limit||0}"></label><label>結帳日<input data-field="statement" type="number" min="1" max="31" value="${a.statement||15}"></label><label>繳款日<input data-field="due" type="number" min="1" max="31" value="${a.due||5}"></label></div><div class="cc-setting-save"><span>帳單週期依結帳日自動計算</span><button class="secondary" data-save-one-card="${a.id}">儲存</button></div></div>`).join(''):'<div class="empty">目前沒有信用卡</div>'}
function renderBudgets(){budgetGrid.innerHTML=state.budgets.map(b=>{let v=monthTx().reduce((a,t)=>a+expenseAmountForCategory(t,b.category),0),c=cat(b.category),p=Math.min(100,v/b.limit*100);return `<div class="budget-card"><div>${c.icon} ${c.name}</div><strong>${money(v)} <small class="hint">/ ${money(b.limit)}</small></strong><div class="progress"><i style="width:${p}%"></i></div><div class="hint">${p.toFixed(0)}% 已使用</div></div>`}).join('')}
function renderRecurring(){recurringGrid.innerHTML=state.recurring.map(r=>`<div class="entity-card"><b>${r.name}</b><strong>${money(r.amount)}</strong><div class="hint">下一次：${r.next}</div></div>`).join('')||'<div class="empty">尚無週期交易</div>'}function renderProjects(){projectGrid.innerHTML=state.projects.map(p=>{let v=state.transactions.filter(t=>t.project===p.id&&t.kind==='expense').reduce((a,t)=>a+t.amount,0);return `<div class="entity-card"><b>${p.name}</b><strong>${money(v)}</strong><div class="hint">預算 ${money(p.budget||0)}</div></div>`}).join('')||'<div class="empty">尚無專案</div>'}function renderCategories(){categoryGrid.innerHTML=state.categories.map(c=>`<div class="entity-card"><div class="mini-icon">${c.icon}</div><b>${c.name}</b><div class="hint">${c.kind==='income'?'收入':'支出'}</div></div>`).join('')}function renderLoans(){loanGrid.innerHTML=state.loans.map(l=>`<div class="entity-card"><b>${l.person}</b><strong>${money(l.amount-l.paid)}</strong><div class="hint">總額 ${money(l.amount)} · 已還 ${money(l.paid)}</div></div>`).join('')||'<div class="empty">尚無借還款</div>'}
function nav(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));document.querySelectorAll('.nav,.mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));pageTitle.textContent={overview:'概覽',transactions:'交易',accounts:'帳戶',analysis:'分析',budgets:'預算',recurring:'週期',projects:'專案',categories:'分類',loans:'借還款',settings:'設定'}[view]||'概覽'}
function openTx(kind='expense',t=null){editId=t?.id||null;modalTitle.textContent=t?'編輯交易':'新增交易';txForm.reset();splitRows.innerHTML='';document.querySelector(`input[name=kind][value="${t?.kind||kind}"]`).checked=true;formDate();if(t){for(let [k,v] of Object.entries(t)){if(k==='splits')continue;let el=txForm.elements[k];if(el)el.value=v}txForm.elements.pending.checked=!!t.pending;if(Array.isArray(t.splits))t.splits.forEach(addSplitRow)}else{txForm.elements.amount.value='';formAccount.selectedIndex=0}updateKind();modalBg.classList.add('open');setTimeout(()=>{window.refreshEntryChoices?.();updateSplitSummary()},0)}
function formDate(){txForm.elements.date.value=editId?(state.transactions.find(t=>t.id===editId)?.date||selectedDate):selectedDate}function updateKind(){document.querySelector('.transfer-only').style.display=document.querySelector('input[name=kind]:checked').value==='transfer'?'block':'none'}
window.editTx=id=>openTx('expense',state.transactions.find(t=>String(t.id)===String(id)));
function closeModals(){modalBg.classList.remove('open');entityBg.classList.remove('open')}
async function submitTx(e){e.preventDefault();let f=new FormData(txForm),kind=f.get('kind'),amount=Number(f.get('amount')||0);if(!amount||amount<0){alert('請輸入有效金額');return}const rows=[...splitRows.querySelectorAll('.split-row')];let splits=rows.map(r=>({category:r.querySelector('[data-split-category]').value,amount:Number(r.querySelector('[data-split-amount]').value||0)})).filter(x=>x.amount>0);if(splits.length){const total=splits.reduce((s,x)=>s+x.amount,0);if(Math.abs(total-amount)>0){alert(`拆帳金額未平衡\n交易金額：${money(amount)}\n拆帳合計：${money(total)}\n差額：${money(Math.abs(amount-total))}`);return}}let t={id:editId||id(),date:f.get('date'),name:f.get('name'),amount,kind,category:f.get('category'),account:f.get('account'),toAccount:f.get('toAccount'),project:f.get('project'),merchant:f.get('merchant'),note:f.get('note'),pending:!!f.get('pending'),splits:splits.length?splits:undefined};if(editId){let old=state.transactions.find(x=>x.id===editId);if(old)adjust(old,-1);state.transactions=state.transactions.map(x=>x.id===editId?t:x)}else state.transactions.push(t);adjust(t,1);await save();window.state=state;window.mozeState=state;closeModals();render();window.refreshEntryChoices?.()}
function adjust(t,sign){if(t.kind==='expense'){let a=acct(t.account);a.balance-=sign*t.amount}else if(t.kind==='income'){let a=acct(t.account);a.balance+=sign*t.amount}else if(t.kind==='transfer'){acct(t.account).balance-=sign*t.amount;acct(t.toAccount).balance+=sign*t.amount}}
function splitCategories(){return state.categories.filter(c=>c.kind==='expense').map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}
function updateSplitSummary(){const amount=Number(txForm.elements.amount.value||0);const rows=[...splitRows.querySelectorAll('.split-row')];const total=rows.reduce((s,r)=>s+Number(r.querySelector('[data-split-amount]')?.value||0),0);const box=document.getElementById('splitSummary');if(!box)return;const diff=amount-total;box.innerHTML=rows.length?`<span>拆帳 ${rows.length} 筆 · 已分配 ${money(total)}</span><b class="${diff===0?'split-ok':'split-warn'}">${diff===0?'✓ 已平衡':'差額 '+money(Math.abs(diff))}</b>`:'<span>未拆帳</span><b>$0</b>';}
function addSplitRow(data={}){let d=document.createElement('div');d.className='split-row';d.innerHTML=`<select data-split-category>${splitCategories()}</select><input data-split-amount type="number" min="0" step="1" placeholder="金額" value="${data.amount||''}"><button type="button" class="icon" data-remove-split>×</button>`;splitRows.appendChild(d);if(data.category)d.querySelector('[data-split-category]').value=data.category;d.querySelector('[data-split-amount]').addEventListener('input',updateSplitSummary);d.querySelector('[data-split-category]').addEventListener('change',updateSplitSummary);d.querySelector('[data-remove-split]').onclick=()=>{d.remove();updateSplitSummary()};updateSplitSummary();}
const entityBgEl=document.getElementById('entityBg'),entityFormEl=document.getElementById('entityForm'),entityTitleEl=document.getElementById('entityTitle'),entityFieldsEl=document.getElementById('entityFields'),cardSettingsEl=document.getElementById('cardSettings');
function openEntity(type){let fields={account:[['name','帳戶名稱'],['balance','初始餘額']],budget:[['limit','預算金額']],project:[['name','專案名稱'],['budget','預算']],category:[['name','分類名稱'],['icon','Icon']],recurring:[['name','名稱'],['amount','金額'],['next','下次日期']],loan:[['person','對象'],['amount','金額']]};entityTitleEl.textContent='新增'+({account:'帳戶',budget:'預算',project:'專案',category:'分類',recurring:'週期交易',loan:'借還款'}[type]);if(type==='account'){entityFieldsEl.innerHTML=`<div class="entity-field"><label>帳戶名稱<input name="name" required></label></div><div class="entity-field"><label>類型<select name="accountType"><option value="bank">銀行</option><option value="cash">現金</option><option value="card">信用卡</option></select></label></div><div class="entity-field"><label>初始餘額／目前欠款<input name="balance" type="number" value="0" required></label></div><div id="newCardFields" style="display:none"><div class="entity-field"><label>信用額度<input name="limit" type="number" min="0" value="50000"></label></div><div class="form-grid"><label>結帳日<input name="statement" type="number" min="1" max="31" value="15"></label><label>繳款日<input name="due" type="number" min="1" max="31" value="5"></label></div></div>`;entityFieldsEl.querySelector('[name=accountType]').onchange=e=>{document.getElementById('newCardFields').style.display=e.target.value==='card'?'block':'none'}}else entityFieldsEl.innerHTML=(fields[type]||[]).map(([n,l])=>`<div class="entity-field"><label>${l}<input name="${n}" type="${n==='amount'||n==='balance'||n==='budget'||n==='limit'?'number':n==='next'?'date':'text'}" required></label></div>`).join('');entityFormEl.dataset.type=type;entityBgEl.classList.add('open')}
async function submitEntity(e){e.preventDefault();let f=new FormData(entityFormEl),type=entityFormEl.dataset.type;if(type==='account'){let at=f.get('accountType')||'bank',bal=Number(f.get('balance')||0);state.accounts.push({id:id(),name:f.get('name'),type:at,balance:at==='card'?-Math.abs(bal):bal,limit:at==='card'?Number(f.get('limit')||0):undefined,statement:at==='card'?Number(f.get('statement')||15):undefined,due:at==='card'?Number(f.get('due')||5):undefined})};if(type==='category')state.categories.push({id:id(),name:f.get('name'),icon:f.get('icon')||'•',kind:'expense'});if(type==='project')state.projects.push({id:id(),name:f.get('name'),budget:Number(f.get('budget')||0)});if(type==='budget')state.budgets.push({id:id(),category:state.categories[0]?.id,limit:Number(f.get('limit')||0)});if(type==='recurring')state.recurring.push({id:id(),name:f.get('name'),amount:Number(f.get('amount')||0),next:f.get('next'),category:state.categories[0]?.id});if(type==='loan')state.loans.push({id:id(),person:f.get('person'),amount:Number(f.get('amount')||0),paid:0});await save();closeModals();render()}

window.MozeApp.openTx=openTx;
window.MozeApp.nav=nav;
window.MozeApp.getState=()=>state;
window.MozeApp.refresh=render;
window.MozeApp.setState=async(next,{persist=true,markDirty=false}={})=>{state=clone(next);window.state=state;window.mozeState=state;if(persist)await save(markDirty);render();window.refreshEntryChoices?.();return state};
window.MozeApp.isReady=true;
window.openTx=openTx;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>nav(b.dataset.view));document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>openTx(b.dataset.quick));
const bind=(el,event,fn)=>{if(el)el.addEventListener(event,fn)};
bind(quickAdd,'click',()=>openTx());bind(mobileAdd,'click',()=>openTx());bind(newTx,'click',()=>openTx());bind(modalClose,'click',closeModals);bind(detailClose,'click',()=>detailBg.classList.remove('open'));bind(detailEdit,'click',()=>{let t=state.transactions.find(x=>String(x.id)===String(window.detailId));detailBg.classList.remove('open');if(t)openTx('expense',t)});bind(detailDelete,'click',()=>deleteTx(window.detailId));bind(modalCancel,'click',closeModals);bind(entityClose,'click',closeModals);bind(entityCancel,'click',closeModals);bind(txForm,'submit',submitTx);bind(entityFormEl,'submit',submitEntity);bind(addSplit,'click',()=>addSplitRow());document.querySelectorAll('input[name=kind]').forEach(x=>x.onchange=updateKind);[txSearch,txType,txCategory,txAccount].forEach(x=>bind(x,'input',renderTransactions));bind(newAccount,'click',()=>openEntity('account'));bind(newBudget,'click',()=>openEntity('budget'));bind(newProject,'click',()=>openEntity('project'));bind(newCategory,'click',()=>openEntity('category'));bind(newRecurring,'click',()=>openEntity('recurring'));bind(newLoan,'click',()=>openEntity('loan'));document.addEventListener('click',e=>{let b=e.target.closest('[data-save-one-card]');if(b){e.preventDefault();let row=b.closest('[data-card-setting]'),a=acct(b.dataset.saveOneCard);if(row&&a){a.limit=Math.max(0,Number(row.querySelector('[data-field=limit]').value||0));a.statement=Math.min(31,Math.max(1,Number(row.querySelector('[data-field=statement]').value||15)));a.due=Math.min(31,Math.max(1,Number(row.querySelector('[data-field=due]').value||5)));save().then(()=>{render();openCreditAccount(a.id)}).catch(err=>alert('儲存失敗：'+err.message))}}});bind(todayBtn,'click',()=>{const now=new Date();selectedDate=now.toISOString().slice(0,10);calendarMonth=new Date(now.getFullYear(),now.getMonth(),1);renderCalendar();renderDaily();renderMetrics();renderChart();renderCards()});bind(prevPeriod,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);selectedDate=monthKey(calendarMonth)+'-01';render()});bind(nextPeriod,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);selectedDate=monthKey(calendarMonth)+'-01';render()});bind(calendarPrev,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()-1);selectedDate=monthKey(calendarMonth)+'-01';renderCalendar();renderDaily();renderMetrics();renderChart();renderCards()});bind(calendarNext,'click',()=>{calendarMonth.setMonth(calendarMonth.getMonth()+1);selectedDate=monthKey(calendarMonth)+'-01';renderCalendar();renderDaily();renderMetrics();renderChart();renderCards()});bind(resetAll,'click',async()=>{if(confirm('確定重設所有示範資料？')){state=clone(seed);await save();render()}});bind(exportJson,'click',()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='moze-backup.json';a.click()});bind(importJson,'click',()=>importFile?.click());bind(importFile,'change',async e=>{let f=e.target.files[0];if(!f)return;try{state=JSON.parse(await f.text());await save();render()}catch{alert('JSON 格式錯誤')}});
(async()=>{try{state=await load();lastPersistedState=clone(state);window.state=state;window.mozeState=state;if(todayLabel)todayLabel.textContent=new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'short'});if(periodLabel)periodLabel.textContent=`${calendarMonth.getFullYear()}/${String(calendarMonth.getMonth()+1).padStart(2,'0')}`;await save(false);render();window.MozeSync?.appReady?.();}catch(err){console.error('MOZE 初始化失敗',err);alert('MOZE 初始化失敗：'+err.message)}})();


(function(){
  const $=id=>document.getElementById(id);
  const input=$('amountInput'),display=$('amountDisplay'),keypad=$('amountKeypad');
  function syncAmount(){if(!input||!display)return;const v=input.value||'';display.textContent=v?Number(v).toLocaleString('zh-TW'):'0';}
  keypad?.addEventListener('click',e=>{const b=e.target.closest('button[data-key]');if(!b)return;const k=b.dataset.key;let v=input.value||'';if(k==='back')v=v.slice(0,-1);else{if(v==='0')v='';if(v.length<12)v+=k;}input.value=v;input.dispatchEvent(new Event('input',{bubbles:true}));syncAmount();});
  input?.addEventListener('input',syncAmount);
  function currentState(){return window.mozeState||window.state;}
  function refresh(){
    const st=currentState(),cc=$('categoryChoices'),ac=$('accountChoices'),cs=$('formCategory'),as=$('formAccount');
    if(!st||!cc||!ac||!cs||!as)return;
    const kind=document.querySelector('input[name="kind"]:checked')?.value||'expense';
    const categories=st.categories.filter(c=>c.kind===kind || (kind==='transfer' && c.kind==='expense'));
    cs.innerHTML=categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
    if(!categories.some(c=>String(c.id)===String(cs.value)))cs.value=categories[0]?.id||'';
    cc.innerHTML=categories.map(c=>`<button type="button" class="choice-chip" data-select="formCategory" data-value="${c.id}"><span class="chip-icon">${svg(c.id)}</span><span class="choice-label">${c.name}</span><span class="checkmark">✓</span></button>`).join('');
    ac.innerHTML=Array.from(as.options).map(o=>{const a=st.accounts.find(x=>String(x.id)===String(o.value));return `<button type="button" class="choice-chip" data-select="formAccount" data-value="${o.value}"><span class="chip-icon">${svg(accountIcon(a))}</span><span class="choice-label">${a?.name||o.text}</span><span class="checkmark">✓</span></button>`}).join('');
    sync();
  }
  function sync(){document.querySelectorAll('.choice-chip').forEach(b=>{const s=$(b.dataset.select);b.classList.toggle('active',!!s&&String(s.value)===String(b.dataset.value));});}
  document.addEventListener('click',e=>{const b=e.target.closest('.choice-chip');if(!b)return;const s=$(b.dataset.select);if(!s)return;s.value=b.dataset.value;s.dispatchEvent(new Event('change',{bubbles:true}));sync();});
  document.querySelectorAll('input[name="kind"]').forEach(r=>r.addEventListener('change',()=>setTimeout(refresh,0)));
  $('formCategory')?.addEventListener('change',sync);$('formAccount')?.addEventListener('change',sync);
  window.refreshEntryChoices=refresh;
  window.mozeState=window.state;
  const originalOpen=window.openTx || (typeof openTx==='function'?openTx:null);
  if(originalOpen){window.openTx=function(kind,t){originalOpen(kind,t);setTimeout(()=>{window.mozeState=window.state;syncAmount();refresh();},0);};}
  setTimeout(()=>{window.mozeState=window.state;syncAmount();refresh();},200);
})();
